<script setup lang="ts">
import { ref } from 'vue'
const photo=ref<File|null>(null), photoPreview=ref(''), saving=ref(false)
function choosePhoto(event:Event){const input=event.target as HTMLInputElement;photo.value=input.files?.[0]||null;photoPreview.value=photo.value?URL.createObjectURL(photo.value):''}
const form=ref({full_name:'',nik:'',birth_place:'',birth_date:'',gender:'L',phone:'',password:'12345678',rt:'',rw:'',full_address:'',working_area:''}),error=ref(''),saved=ref('')
async function submit(){if(saving.value)return;saving.value=true;error.value='';saved.value='';try{const body=new FormData();Object.entries(form.value).forEach(([key,value])=>body.append(key,String(value)));if(photo.value)body.append('photo',photo.value);const r=await fetch(`${import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1'}/cadres`,{method:'POST',headers:{Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'},body});const p=await r.json();if(!r.ok)throw new Error(p.message??'Gagal menyimpan kader.');saved.value='Kader dan akun login berhasil disimpan di MySQL.'}catch(e){error.value=e instanceof Error?e.message:'Gagal menyimpan kader.'}finally{saving.value=false}}
</script>
<template><main class="admin-page cadre-create"><section class="admin-content"><header><div><p>Data Kader / Pendaftaran</p><h1>Tambah Kader</h1><p class="page-subtitle">Lengkapi profil kader untuk memudahkan pasien mengenali pendampingnya.</p></div><a class="add-button" href="/admin/cadres">← Kembali</a></header><form class="cadre-form" @submit.prevent="submit"><section class="cadre-section"><div class="section-head"><b>01</b><div><h2>Identitas dan foto kader</h2><p>Gunakan data sesuai identitas resmi dan foto terbaru.</p></div></div><div class="cadre-grid"><label class="photo-field">Foto kader <small>JPG, PNG, atau WEBP maksimal 2 MB.</small><input type="file" accept="image/jpeg,image/png,image/webp" @change="choosePhoto" required><img v-if="photoPreview" :src="photoPreview" alt="Preview foto kader"></label><div class="cadre-grid nested"><label>Nama lengkap<input v-model="form.full_name" placeholder="Nama sesuai identitas" required></label><label>NIK<input v-model="form.nik" inputmode="numeric" pattern="[0-9]{16}" maxlength="16" placeholder="16 digit NIK" required></label><label>Tempat lahir<input v-model="form.birth_place" required></label><label>Tanggal lahir<input v-model="form.birth_date" type="text" inputmode="numeric" placeholder="DD/MM/YYYY" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" required><small>Format: DD/MM/YYYY</small></label><label>Jenis kelamin<select v-model="form.gender"><option value="L">Laki-laki</option><option value="P">Perempuan</option></select></label></div></div></section><section class="cadre-section"><div class="section-head"><b>02</b><div><h2>Akun dan kontak</h2><p>Nomor HP dan password dipakai kader untuk masuk aplikasi.</p></div></div><div class="cadre-grid"><label>Nomor HP<input v-model="form.phone" type="tel" placeholder="Contoh: 081234567890" required><small>Gunakan nomor aktif.</small></label><label>Password login<input v-model="form.password" type="password" minlength="8" required><small>Minimal 8 karakter.</small></label></div></section><section class="cadre-section"><div class="section-head"><b>03</b><div><h2>Alamat dan wilayah binaan</h2><p>Informasi ini membantu pembagian tugas pendampingan.</p></div></div><div class="cadre-grid"><label>RT<input v-model="form.rt" maxlength="3" placeholder="Contoh: 001" required></label><label>RW<input v-model="form.rw" maxlength="3" placeholder="Contoh: 009" required></label><label class="wide">Alamat lengkap<textarea v-model="form.full_address" placeholder="Nama jalan, kelurahan, kecamatan, kota" required /></label></div></section><p v-if="error" class="error">{{error}}</p><p v-if="saved" class="success">{{saved}}</p><div class="cadre-actions"><p>Periksa foto dan identitas sebelum menyimpan.</p><button class="save-button" :disabled="saving">{{saving?'Menyimpan…':'Simpan Kader'}}</button></div></form></section></main></template><style scoped>
.cadre-create .admin-content{max-width:1120px;margin:auto}.cadre-create header{align-items:flex-start}.page-subtitle{font-size:12px;color:#698496;margin:5px 0}.cadre-form{background:none;border:0;box-shadow:none;padding:0}.cadre-section{background:#fff;border:1px solid #dfedeb;border-radius:14px;padding:24px;margin-bottom:16px;box-shadow:0 8px 22px #28766b0b}.section-head{display:flex;gap:12px;border-bottom:1px solid #edf3f1;padding-bottom:15px;margin-bottom:20px}.section-head>b{display:grid;place-items:center;width:34px;height:34px;background:#e1f5ee;border-radius:10px;color:#087e78}.section-head h2{font-size:16px;margin:0}.section-head p{font-size:12px;color:#718b92;margin:4px 0}.cadre-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 24px;align-items:start}.cadre-grid.nested{grid-column:span 2}.cadre-grid label{display:block;font-size:13px;font-weight:600}.cadre-grid input,.cadre-grid select,.cadre-grid textarea{display:block;width:100%;margin-top:8px;padding:11px 12px;border:1px solid #cddfdf;border-radius:9px;background:#fcfefe;font:14px Arial;min-height:44px}.cadre-grid textarea{min-height:100px;resize:vertical}.cadre-grid small{display:block;font-size:11px;font-weight:normal;color:#718b92;margin-top:5px}.photo-field{grid-row:span 2}.photo-field input{padding:10px}.photo-field img{display:block;width:150px;height:180px;object-fit:cover;border-radius:12px;margin-top:12px;border:2px solid #bde2d8}.full-row,.wide{grid-column:1/-1}.cadre-actions{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px 20px;background:#fff;border:1px solid #dfedeb;border-radius:12px}.cadre-actions p{margin:0;color:#718b92;font-size:12px}.cadre-actions button{padding:13px 24px}@media(max-width:700px){.cadre-section{padding:18px}.cadre-grid,.cadre-grid.nested{grid-template-columns:1fr;grid-column:auto}.photo-field{grid-row:auto}.cadre-actions{flex-direction:column;align-items:stretch}.cadre-actions button{width:100%}}
</style>
